import io
import json
import os
import unittest
import urllib.error
from unittest.mock import patch
import openai_client

class ClientTests(unittest.TestCase):
    @patch.dict(os.environ, {'OPENAI_API_KEY': 'test-key'})
    @patch('urllib.request.urlopen')
    def test_request_and_text(self, urlopen):
        urlopen.return_value.__enter__.return_value = io.BytesIO(json.dumps({
            'status': 'completed',
            'output': [{'type': 'reasoning'}, {'type': 'message', 'content': [
                {'type': 'output_text', 'text': 'Hello'},
                {'type': 'output_text', 'text': ' world'}]}]
        }).encode())
        self.assertEqual(openai_client.send_private_prompt('private text'), 'Hello world')
        request = urlopen.call_args.args[0]
        self.assertEqual(request.full_url, 'https://api.openai.com/v1/responses')
        self.assertEqual(request.get_header('Authorization'), 'Bearer test-key')
        self.assertEqual(json.loads(request.data), {'model': 'gpt-4.1-mini', 'input': 'private text', 'store': False})

    @patch.dict(os.environ, {'OPENAI_API_KEY': 'test-key'})
    @patch('urllib.request.urlopen')
    def test_http_error_does_not_leak_body(self, urlopen):
        urlopen.side_effect = urllib.error.HTTPError('https://api.openai.com/v1/responses', 400, 'bad', {}, io.BytesIO(b'private text'))
        with self.assertRaises(openai_client.OpenAIClientError) as error:
            openai_client.send_private_prompt('private text')
        self.assertEqual(str(error.exception), 'OpenAI API returned HTTP 400')

    @patch.dict(os.environ, {'OPENAI_API_KEY': 'test-key'})
    @patch('urllib.request.urlopen')
    def test_no_output(self, urlopen):
        urlopen.return_value.__enter__.return_value = io.BytesIO(b'{\"output\": []}')
        with self.assertRaisesRegex(openai_client.OpenAIClientError, 'returned no text'):
            openai_client.send_private_prompt('private text')

unittest.main()
